join public.exam_boards b on b.name = v.banca and b.user_id is null
join public.disciplines d on d.name = v.disciplina_nome and d.user_id is null
join public.question_sets qs on qs.name = v.name and qs.source = 'TEC Concursos - Índice de Assuntos' and qs.discipline_id = d.id
on conflict (board_id, question_set_id) do update set quantidade = excluded.quantidade, percentual = excluded.percentual, periodo = excluded.periodo, is_leaf = excluded.is_leaf;;
